window.PRACTICE_EXTRA = Object.assign(window.PRACTICE_EXTRA || {}, {"wr1":{"caption":{"zh":"写一封道歉/改期邮件,写完点「检查反馈」即时自查,再看范文。","en":"Write an apology / reschedule email, press Get feedback for an instant self-check, then compare with the model."},"writing":{"storeKey":"wr1","prompt":{"zh":"给同事写一封简短邮件:为错过今天的会议道歉,简要说明原因,并提议本周改到另一个具体时间。","en":"Write a short email to a colleague: apologise for missing today's meeting, give a brief reason, and propose one specific new time this week."},"minWords":45,"maxWords":90,"mustInclude":[{"label":{"zh":"称呼(Dear / Hi + 名字)","en":"A greeting (Dear / Hi + name)"},"keywords":["dear","hi ","hello","hey"]},{"label":{"zh":"道歉","en":"An apology"},"keywords":["sorry","apolog","my apologies"]},{"label":{"zh":"简短原因","en":"A brief reason"},"keywords":["because","due to","came up","i had","i was","as i","since"]},{"label":{"zh":"提议一个具体新时间","en":"A specific new time"},"keywords":["reschedul","how about","would ","could we","are you free","monday","tuesday","wednesday","thursday","friday","a.m","p.m","am","pm","o'clock"]},{"label":{"zh":"礼貌结尾(Regards / Thanks)","en":"A polite closing (Regards / Thanks)"},"keywords":["regards","best wishes","thanks","thank you","look forward","sincerely","cheers"]}],"checklist":[{"zh":"有称呼和落款,读起来像一封邮件","en":"Has a greeting and a sign-off — it reads like an email"},{"zh":"真诚道歉,不过度解释找借口","en":"Apologises sincerely, without over-explaining"},{"zh":"给出一个清晰、具体的新时间","en":"Offers one clear, specific new time"},{"zh":"语气礼貌、简洁","en":"Polite and concise in tone"}],"frames":[{"zh":"I'm really sorry I missed our meeting this morning.","en":"I'm really sorry I missed our meeting this morning."},{"zh":"Something urgent came up and I couldn't get away in time.","en":"Something urgent came up and I couldn't get away in time."},{"zh":"I apologise for any inconvenience this may have caused.","en":"I apologise for any inconvenience this may have caused."},{"zh":"Could we reschedule for later this week?","en":"Could we reschedule for later this week?"},{"zh":"Would Thursday at 2 p.m. work for you?","en":"Would Thursday at 2 p.m. work for you?"},{"zh":"Thanks for your understanding. Best regards, …","en":"Thanks for your understanding. Best regards, …"}],"model":{"en":"Hi Sam,\n\nI'm really sorry I missed our meeting this morning. A last-minute problem came up with a client and I couldn't get away in time. I apologise for any inconvenience.\n\nCould we reschedule for later this week? Would Thursday at 2 p.m. work for you? If not, just let me know a time that suits you.\n\nThanks for your understanding.\n\nBest regards,\nWei","zh":"一封得体的道歉邮件:称呼 → 真诚道歉 → 简短原因 → 提议一个具体新时间(周四下午 2 点)→ 礼貌结尾与落款。"}}},"wr2":{"caption":{"zh":"写一封咨询/询问邮件,写完点「检查反馈」即时自查,再看范文。","en":"Write a request / enquiry email, press Get feedback for an instant self-check, then compare with the model."},"writing":{"storeKey":"wr2","prompt":{"zh":"给一所语言学校(或酒店)写一封简短邮件,咨询暑期英语课程的信息:先打招呼,说明写信目的,提出 2–3 个清晰的问题,请对方回复,并礼貌结尾。","en":"Write a short email to a language school (or a hotel) to ask for information about a summer English course: greet the reader, say why you are writing, ask 2–3 clear questions, request a reply, and close politely."},"minWords":50,"maxWords":95,"mustInclude":[{"label":{"zh":"称呼(Dear / Hello + 名字或 Sir/Madam)","en":"A greeting (Dear / Hello + name or Sir/Madam)"},"keywords":["dear","hello","hi ","to whom","sir","madam"]},{"label":{"zh":"写信目的","en":"The reason for writing"},"keywords":["i am writing","i'm writing","writing to","i would like to","i'd like to","i am interested","i'm interested","enquir","inquir","ask about","regarding","about your","find out","information about","some information"]},{"label":{"zh":"2–3 个清晰的问题","en":"2–3 clear questions"},"keywords":["?","could you tell me","i would like to know","i would also like","how much","how long","how many","what time","do you","is there","are there","when ","what is","what are"]},{"label":{"zh":"请求回复","en":"A request for a reply"},"keywords":["look forward to hearing","look forward to your reply","please let me know","hope to hear","get back to me","reply","respond","your response","hearing from you"]},{"label":{"zh":"礼貌结尾(Regards / Yours ...)","en":"A polite closing (Regards / Yours ...)"},"keywords":["regards","best wishes","yours faithfully","yours sincerely","sincerely","kind regards","thanks","thank you","many thanks"]}],"checklist":[{"zh":"有称呼和落款,读起来像一封询问邮件","en":"Has a greeting and a sign-off — it reads like an enquiry email"},{"zh":"开头就说清写信目的","en":"States the purpose clearly at the start"},{"zh":"提出 2–3 个具体、清晰的问题","en":"Asks 2–3 specific, clear questions"},{"zh":"语气礼貌、较为正式","en":"Polite and fairly formal in tone"}],"frames":[{"zh":"I am writing to ask for some information about your summer English courses.","en":"I am writing to ask for some information about your summer English courses."},{"zh":"I found your school online and I would like to know a few details.","en":"I found your school online and I would like to know a few details."},{"zh":"Could you tell me how much a four-week course costs?","en":"Could you tell me how much a four-week course costs?"},{"zh":"How long is each lesson, and how many students are there in a class?","en":"How long is each lesson, and how many students are there in a class?"},{"zh":"I would be grateful if you could reply by the end of the week.","en":"I would be grateful if you could reply by the end of the week."},{"zh":"I look forward to hearing from you. Yours faithfully, …","en":"I look forward to hearing from you. Yours faithfully, …"}],"model":{"en":"Dear Sir or Madam,\n\nI am writing to ask for some information about your summer English courses. I found your school online and I am interested in improving my speaking.\n\nCould you tell me how much a four-week course costs? How many students are there in each class, and do you offer lessons in the evening?\n\nI would be grateful for a reply by Friday. I look forward to hearing from you.\n\nYours faithfully,\nAna Ruiz","zh":"一封礼貌的询问邮件:称呼 → 说明写信目的 → 提出 2–3 个清晰问题(费用、班级人数、上课时间)→ 请求回复 → 正式结尾与落款。"}}},"wr3":{"caption":{"zh":"就一个观点写一段议论文字,写完点「检查反馈」即时自查,再看范文。","en":"Write an opinion paragraph on a statement, press Get feedback for an instant self-check, then compare with the model."},"writing":{"storeKey":"wr3","prompt":{"zh":"针对这句话写一段观点文字:「在家办公比在办公室办公更好。」请表明清晰立场,先写一句主题句,给出一两个理由和一个例子,最后用一句结论收尾。","en":"Write one paragraph responding to this statement: \"Working from home is better than working in an office.\" Take a clear position, start with a topic sentence, give one or two reasons and an example, and finish with a concluding sentence."},"minWords":60,"maxWords":120,"mustInclude":[{"label":{"zh":"清晰的立场(主题句)","en":"A clear position (topic sentence)"},"keywords":["i think","i believe","in my opinion","i agree","i disagree","i feel","personally","from my point of view","in my view","it seems to me","i would say","i would argue"]},{"label":{"zh":"至少一个理由","en":"At least one reason"},"keywords":["because","since","one reason","the main reason","the reason","this is because","due to","for this reason","reason is","firstly","first of all","as it"]},{"label":{"zh":"一个具体例子","en":"A concrete example"},"keywords":["for example","for instance","such as","in my case","to give an example","a good example","like when","when i","e.g"]},{"label":{"zh":"衔接词/第二个理由(递进或转折)","en":"A linking word / second reason (addition or contrast)"},"keywords":["however","in addition","moreover","also","another","on the other hand","furthermore","besides","what is more","secondly","as well","not only"]},{"label":{"zh":"结论句","en":"A concluding sentence"},"keywords":["in conclusion","to conclude","overall","to sum up","in summary","all in all","therefore","for these reasons","that is why","in short","clearly"]}],"checklist":[{"zh":"第一句就亮明清晰的观点(主题句)","en":"States a clear opinion in the first sentence (topic sentence)"},{"zh":"给出至少一个理由来支撑观点","en":"Gives at least one reason to support the opinion"},{"zh":"包含一个具体的例子","en":"Includes a concrete example"},{"zh":"用一句结论收尾,呼应开头观点","en":"Ends with a concluding sentence that echoes the opinion"}],"frames":[{"zh":"In my opinion, working from home is better than working in an office.","en":"In my opinion, working from home is better than working in an office."},{"zh":"I feel this way for two main reasons.","en":"I feel this way for two main reasons."},{"zh":"One reason is that I save a lot of time on travelling.","en":"One reason is that I save a lot of time on travelling."},{"zh":"For example, last year I worked from home and got more done each day.","en":"For example, last year I worked from home and got more done each day."},{"zh":"However, some people find it harder to focus at home.","en":"However, some people find it harder to focus at home."},{"zh":"Overall, I believe the benefits clearly outweigh the drawbacks.","en":"Overall, I believe the benefits clearly outweigh the drawbacks."}],"model":{"en":"In my opinion, working from home is better than working in an office. I feel this way for two main reasons. Firstly, I save a lot of time because I do not have to travel to work. For example, last year my commute took two hours a day, and now I use that time to rest or study. In addition, I can concentrate better in a quiet room. However, I understand that some people miss seeing their colleagues. Overall, I believe that working from home suits me best and makes me more productive.","zh":"一段规范的观点文字:主题句表明立场 → 第一个理由(省下通勤时间)+ 例子 → 递进第二个理由(更专注)→ 一句让步转折 → 结论句呼应开头。"}}},"wr4":{"caption":{"zh":"写一封投诉邮件,写完点「检查反馈」即时自查,再看范文。","en":"Write a complaint email, press Get feedback for an instant self-check, then compare with the model."},"writing":{"storeKey":"wr4","prompt":{"zh":"给网店客服写一封投诉邮件:说明你买了什么、何时购买,描述商品出了什么问题(如损坏或无法使用),表达你的感受,并要求退款或换货。语气要礼貌但坚定。","en":"Write a complaint email to an online shop about a product that arrived faulty. Say what you bought and when, describe the problem, explain how you feel, and ask for a refund or a replacement. Keep a polite but firm tone."},"minWords":55,"maxWords":100,"mustInclude":[{"label":{"zh":"称呼(Dear + 客服/名字)","en":"A greeting (Dear + name / customer service)"},"keywords":["dear","hi ","hello","to whom","madam","customer service","team"]},{"label":{"zh":"买了什么、何时购买(含订单信息)","en":"What you bought and when (with order details)"},"keywords":["bought","purchased","order","i received","delivered","delivery","last week","last month","days ago","from your","your store","your website","your shop","online"]},{"label":{"zh":"商品的问题或故障","en":"The problem or fault"},"keywords":["broken","faulty","fault","damaged","not work","doesn't work","didn't work","stopped working","defect","wrong","missing","poor","scratch","crack","leak","torn","won't","error","problem","issue","never arrived","not as described"]},{"label":{"zh":"你想要的结果(退款/换货/道歉)","en":"What you want (refund / replacement / apology)"},"keywords":["refund","replace","replacement","money back","exchange","repair","fix","apolog","compensat","resolve","sort this out","put this right"]},{"label":{"zh":"礼貌但坚定的结尾","en":"A polite but firm closing"},"keywords":["look forward","hearing from you","as soon as possible","prompt","within","regards","sincerely","faithfully","yours","thank you","thanks","reply","response","await","expect"]}],"checklist":[{"zh":"有称呼和落款,读起来像一封正式邮件","en":"Has a greeting and a sign-off — it reads like a formal email"},{"zh":"清楚说明买了什么、哪里出了问题","en":"Clearly states what was bought and what went wrong"},{"zh":"表达失望或不满,但不粗鲁","en":"Expresses disappointment without being rude"},{"zh":"提出明确、具体的要求,并以坚定而礼貌的方式收尾","en":"Makes a clear, specific request with a firm, polite closing"}],"frames":[{"zh":"I am writing to complain about a product I bought from your website.","en":"I am writing to complain about a product I bought from your website."},{"zh":"On 5 August I ordered a coffee machine (order no. 7312).","en":"On 5 August I ordered a coffee machine (order no. 7312)."},{"zh":"Unfortunately, when it arrived, the item was faulty and would not switch on.","en":"Unfortunately, when it arrived, the item was faulty and would not switch on."},{"zh":"I am very disappointed, as this is the second time this has happened.","en":"I am very disappointed, as this is the second time this has happened."},{"zh":"I would therefore like a full refund or a replacement as soon as possible.","en":"I would therefore like a full refund or a replacement as soon as possible."},{"zh":"I look forward to your prompt reply. Yours faithfully, …","en":"I look forward to your prompt reply. Yours faithfully, …"}],"model":{"en":"Dear Customer Service Team,\n\nI am writing to complain about a coffee machine I bought from your website on 5 August (order no. 7312).\n\nUnfortunately, when it arrived, the machine was faulty: it leaks water and will not heat up. I am very disappointed, especially as delivery already took two weeks.\n\nI would therefore like a full refund or a replacement as soon as possible. Please let me know how to return the item.\n\nI look forward to your prompt reply.\n\nYours faithfully,\nLi Wei","zh":"一封得体的投诉邮件:称呼 → 说明购买的商品与时间(含订单号)→ 描述故障 → 表达失望 → 提出退款/换货要求 → 礼貌而坚定的结尾与落款。"}}},"wr5":{"caption":{"zh":"描述一张折线图(雅思写作 Task 1 风格),写完点「检查反馈」即时自查,再看范文。","en":"Describe a line graph (IELTS Task 1 style), press Get feedback for an instant self-check, then compare with the model."},"writing":{"storeKey":"wr5","prompt":{"zh":"用一段话描述下面这张折线图(雅思写作 Task 1 风格)。它显示某咖啡品牌 2018 至 2023 年的线上销量(单位:千件):2018=20,2019=35,2020=60,2021=55,2022=80,2023=110。先写一句总体趋势概述,再用具体数字、年份、趋势动词和至少一处比较来支撑。不要给出原因或个人观点。","en":"Describe the line graph below in one paragraph, as in IELTS Writing Task 1. It shows the online sales of a coffee brand (in thousands of units) from 2018 to 2023: 2018 = 20, 2019 = 35, 2020 = 60, 2021 = 55, 2022 = 80, 2023 = 110. Begin with an overview of the main trend, then support it with specific figures, years, trend verbs and at least one comparison. Do not give reasons or opinions."},"minWords":55,"maxWords":100,"mustInclude":[{"label":{"zh":"总体趋势概述句","en":"An overview of the main trend"},"keywords":["overall","in general","generally","the graph shows","the chart shows","the line graph","it is clear","clearly","overview","main trend","as a whole","on the whole","most striking","most noticeable"]},{"label":{"zh":"趋势动词(上升/下降/持平/达峰值)","en":"Trend language (rise / fall / peak / stable)"},"keywords":["rose","rise","increas","grew","grow","went up","climb","fell","fall","drop","declin","decreas","dip","peak","remain","stable","steady","levelled","leveled","fluctuat","plateau","doubled","reached","recover"]},{"label":{"zh":"具体数字与单位","en":"Specific figures and units"},"keywords":["thousand","units",",000","35","45","55","60","65","70","80","90","100","110","120"]},{"label":{"zh":"具体年份","en":"Specific years"},"keywords":["2018","2019","2020","2021","2022","2023","over the period","each year","the following year","that year","six years"]},{"label":{"zh":"至少一处比较","en":"At least one comparison"},"keywords":["compared","comparison","than","while","whereas","whilst","higher","lower","more than","less than","twice","double","half","the highest","the lowest","greatest","smallest","in contrast","unlike","as high as","times"]}],"checklist":[{"zh":"开头一句概括图表内容与主要趋势","en":"Opens by summarising what the graph shows and the main trend"},{"zh":"使用准确的趋势动词(rose / fell / peaked / remained stable)","en":"Uses accurate trend verbs (rose, fell, peaked, remained stable)"},{"zh":"用具体的年份和数字支撑描述","en":"Supports the description with specific years and figures"},{"zh":"至少包含一处比较(如高于/是……的几倍)","en":"Includes at least one comparison (e.g. higher than, several times)"}],"frames":[{"zh":"The line graph shows the online sales of a coffee brand between 2018 and 2023.","en":"The line graph shows the online sales of a coffee brand between 2018 and 2023."},{"zh":"Overall, sales rose significantly over the period, despite one small dip.","en":"Overall, sales rose significantly over the period, despite one small dip."},{"zh":"In 2018, sales stood at about 20,000 units.","en":"In 2018, sales stood at about 20,000 units."},{"zh":"They then climbed steadily, reaching a peak of 110,000 units in 2023.","en":"They then climbed steadily, reaching a peak of 110,000 units in 2023."},{"zh":"There was a slight dip in 2021, when the figure fell to 55,000.","en":"There was a slight dip in 2021, when the figure fell to 55,000."},{"zh":"Sales in 2023 were more than five times higher than in 2018.","en":"Sales in 2023 were more than five times higher than in 2018."}],"model":{"en":"The line graph shows the online sales of a coffee brand, measured in thousands of units, between 2018 and 2023.\n\nOverall, sales rose sharply over the period, despite one small dip. In 2018, the figure stood at just 20,000 units. It then climbed steadily to 60,000 in 2020.\n\nIn 2021, sales fell slightly to 55,000, but they soon recovered, reaching 80,000 in 2022. By 2023, they had peaked at 110,000 units, over five times the 2018 figure.","zh":"一段雅思 Task 1 描述:概述总体上升趋势 → 用具体年份与数字描述各阶段(起点、攀升、2021 小幅回落、回升)→ 指出 2023 达到峰值并与 2018 作倍数比较。"}}},"wr6":{"caption":{"zh":"写一个正反观点(利弊)段落,写完点「检查反馈」即时自查,再看范文。","en":"Write a for-and-against (pros and cons) paragraph, press Get feedback for an instant self-check, then compare with the model."},"writing":{"storeKey":"wr6","prompt":{"zh":"就一个话题写一个正反观点段落(如「智能手机的利与弊」,也可选在线学习、城市生活 vs 乡村生活):先用主题句点明话题,给出至少一个优点(配连接词),再用转折词转到至少一个缺点,最后用一句带自己观点的话做平衡总结。","en":"Write a for-and-against paragraph on a topic (e.g. 'the advantages and disadvantages of smartphones', or online learning, or city vs country living): open with a topic sentence, give at least one advantage (with a linker), turn to at least one disadvantage (with a contrast linker), and finish with one balanced sentence that gives your own view."},"minWords":70,"maxWords":120,"mustInclude":[{"label":{"zh":"主题句(点明话题)","en":"A topic sentence (state the topic)"},"keywords":["advantages and disadvantages","pros and cons","benefits and drawbacks","both","nowadays","these days","today","in recent years","has become","have become","part of","many people","more and more","when it comes to","the topic of","widely","everywhere","smartphone","online learning","living in","the internet"]},{"label":{"zh":"一个优点 + 连接词","en":"An advantage with a linker"},"keywords":["one advantage","an advantage","the main advantage","a clear advantage","an obvious advantage","one benefit","a benefit","a major benefit","on the one hand","firstly","first of all","for one thing","to begin with","the positive","a positive","advantage is","benefit is","it allows","allow us","it helps","help us","it lets","lets us","makes it easier","convenient","convenience","save time","saves time"]},{"label":{"zh":"一个缺点 + 转折连接词","en":"A disadvantage with a contrast linker"},"keywords":["however","on the other hand","a drawback","the drawback","one drawback","a disadvantage","the disadvantage","one disadvantage","the downside","a downside","on the downside","the main drawback","a major drawback","nevertheless","even so","in contrast","although","though","but ","yet ","a problem","one problem","the problem is","a negative","a serious"]},{"label":{"zh":"一个理由或例子","en":"A reason or an example"},"keywords":["because","for example","for instance","such as","this means","which means","as a result","so that","since","due to","e.g","in other words","this is because"]},{"label":{"zh":"结论 + 自己的观点","en":"A concluding opinion (your own view)"},"keywords":["overall","in conclusion","to conclude","in my view","in my opinion","to sum up","in summary","on balance","all in all","i believe","i think","personally","i feel","in the end","outweigh","outweighs","weigh up","my own view","i would say","to summarise","to summarize"]}],"checklist":[{"zh":"主题句点明话题,读起来平衡、不一开始就偏一边","en":"The topic sentence names the topic and stays balanced"},{"zh":"优点、缺点各至少一个,并用连接词衔接","en":"At least one advantage and one disadvantage, each joined with a linker"},{"zh":"用转折词(however / on the other hand)清晰转到另一面","en":"A contrast linker clearly signals the other side"},{"zh":"结尾给出自己的观点,而不只是罗列两面","en":"The ending gives your own view, not just a list of points"}],"frames":[{"zh":"Smartphones have become a part of everyday life, and they bring both benefits and drawbacks.","en":"Smartphones have become a part of everyday life, and they bring both benefits and drawbacks."},{"zh":"On the one hand, one clear advantage is that they let us stay connected wherever we are.","en":"On the one hand, one clear advantage is that they let us stay connected wherever we are."},{"zh":"For example, we can message family, check maps and pay bills in just a few seconds.","en":"For example, we can message family, check maps and pay bills in just a few seconds."},{"zh":"On the other hand, a serious drawback is that they can be addictive and distracting.","en":"On the other hand, a serious drawback is that they can be addictive and distracting."},{"zh":"However, spending too long on a screen can harm our sleep and concentration.","en":"However, spending too long on a screen can harm our sleep and concentration."},{"zh":"Overall, in my view the benefits outweigh the problems, as long as we use them sensibly.","en":"Overall, in my view the benefits outweigh the problems, as long as we use them sensibly."}],"model":{"en":"Smartphones have quickly become part of daily life, and they bring both clear benefits and real drawbacks. On the one hand, one obvious advantage is convenience: they let us message friends, find directions and pay for things in seconds, wherever we are. On the other hand, a serious drawback is that they can be very distracting. Many people, for example, check their phones constantly and sleep badly because of them. Overall, in my view the advantages outweigh the disadvantages, but only if we set limits and put the phone down sometimes.","zh":"一个正反观点段落:主题句点明话题 →(on the one hand)给出一个优点并举例 →(on the other hand / however)转到一个缺点 → 结尾用 overall / in my view 给出自己的平衡结论。"}}}});
